 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if len(ones) >= 2:
        # Connect any pair of 1 markers that share a diagonal.
        for i, (r1, c1) in enumerate(ones):
            for r2, c2 in ones[i+1:]:
                if abs(r2-r1) == abs(c2-c1):
                    dr = 1 if r2 > r1 else -1
                    dc = 1 if c2 > c1 else -1
                    r, c = r1, c1
                    while True:
                        out[r][c] = 1
                        if (r,c)==(r2,c2): break
                        r += dr; c += dc
    # Each 6 marker extends on its down-right diagonal; 6 overrides 1 at crossings.
    for sr, sc in sixes:
        r, c = sr, sc
        while 0 <= r-1 < h and 0 <= c-1 < w:
            r -= 1; c -= 1
        while 0 <= r < h and 0 <= c < w:
            out[r][c] = 6
            r += 1; c += 1
    return out
