        best=None
        for i,(r1,c1) in enumerate(ones):
            for r2,c2 in ones[i+1:]:
                if abs(r2-r1)==abs(c2-c1):
                    d=abs(r2-r1)
                    if best is None or d>best[0]: best=(d,(r1,c1),(r2,c2))
        if best:
            _,(r1,c1),(r2,c2)=best
            dr=1 if r2>r1 else -1; dc=1 if c2>c1 else -1
            r,c=r1,c1
            while True:
                if grid[r][c]!=6:out[r][c]=1
                if (r,c)==(r2,c2):break
                r+=dr;c+=dc
    # Each 6 forms a diagonal of constant r-c, drawn across the whole grid.
    for sr,sc in sixes:
        diff=sr-sc
        for r in range(h):
            c=r-diff
            if 0<=c<w and out[r][c]!=1:
                out[r][c]=6
    return out
