                dr=1 if r2>r1 else -1
                dc=1 if c2>c1 else -1
                r,c=r1,c1
                while True:
                    out[r][c]=1
                    if (r,c)==(r2,c2): break
                    r+=dr; c+=dc
    # Group 6 markers by diagonal (constant column-row). A singleton extends
    # across the whole canvas; multiple collinear markers connect only as a segment.
    groups={}
    for r,c in sixes: groups.setdefault(c-r,[]).append((r,c))
    for d,pts in groups.items():
