            while r>0 and c>0: r-=1; c-=1
            while r<h and c<w:
                out[r][c]=6
                r+=1;c+=1
        else:
            (r1,c1),(r2,c2)=min(pts),max(pts)
            r,c=r1,c1
            while True:
                out[r][c]=6
                if (r,c)==(r2,c2): break
                r+=1;c+=1
    return out
